def relerr(a, b):
    num = 0.0
    den = 0.0
    if isinstance(a[0], list):
        for i in range(len(a)):
            for j in range(len(a[i])):
                num += (a[i][j] - b[i][j]) ** 2
                den += a[i][j] ** 2 + b[i][j] ** 2
    else:
        for i in range(len(a)):
            num += (a[i] - b[i]) ** 2
            den += a[i] ** 2 + b[i] ** 2
    return math.sqrt(num / den) if den > 0 else math.sqrt(num)

